class Task {

    private static int mod = 998244353;

    public long powMod(long a, long b) {
        long ans = 1, d = a;
        while (b > 0) {
            if (b % 2 == 1) ans = ans * d % mod;
            b >>= 1;
            d = d * d % mod;
        }
        return ans;
    }

    long[] fac, inv;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        //int T = in.nextInt();
        int n = 200001;
        fac = new long[n];
        inv = new long[n];
        fac[0] = inv[0] = 1;
        for (int i = 1; i < n; i++) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = inv[i - 1] * powMod(i, mod - 2) % mod;
        }
        //for (int tc = 1; tc <= T; tc++) {
            n = in.nextInt();
